-- Runs only in the disposable database created by Test-CRM-TypePage.ps1 -IncludeManagement.
IF DB_NAME() NOT LIKE 'Prosto_CRM_Page_Test[_]%' THROW 51299,'An isolated CRM test database is required.',1;
DECLARE @Results TABLE(Test nvarchar(200));
DECLARE @Saved TABLE(ID int,Row_Version binary(8));
INSERT @Saved EXEC dbo.CRM_Save_WorkGuide_Category @Actor_ID=1,@Data=N'<row><Brand_ID>1</Brand_ID><Name_AR>جذر SQL</Name_AR><Name_EN>SQL Root</Name_EN><Sort_Order>10</Sort_Order></row>';
DECLARE @Root int=(SELECT ID FROM @Saved),@RootVersion binary(8)=(SELECT Row_Version FROM @Saved);DELETE @Saved;
DECLARE @Data xml=CONVERT(xml,CONCAT(N'<row><Brand_ID>1</Brand_ID><Parent_ID>',@Root,N'</Parent_ID><Name_AR>فرع SQL</Name_AR><Name_EN>SQL Child</Name_EN><Sort_Order>2</Sort_Order></row>'));
INSERT @Saved EXEC dbo.CRM_Save_WorkGuide_Category @Actor_ID=1,@Data=@Data;
DECLARE @Child int=(SELECT ID FROM @Saved);DELETE @Saved;
INSERT @Saved EXEC dbo.CRM_Save_WorkGuide_Category @Actor_ID=1,@Data=N'<row><Brand_ID>1</Brand_ID><Name_AR>جذر SQL ثان</Name_AR><Name_EN>Other SQL Root</Name_EN><Sort_Order>1</Sort_Order></row>';
DECLARE @Other int=(SELECT ID FROM @Saved);DELETE @Saved;
BEGIN TRY EXEC dbo.CRM_Save_WorkGuide_Category @Actor_ID=2,@Data=N'<row><Brand_ID>1</Brand_ID><Name_AR>مرفوض</Name_AR><Name_EN>Denied</Name_EN><Sort_Order>0</Sort_Order></row>';THROW 51299,'Owner managed guide categories',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51200 THROW;END CATCH;
BEGIN TRY EXEC dbo.CRM_Select_WorkGuide_Items @Actor_ID=2;THROW 51299,'Owner read guide items',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51200 THROW;END CATCH;
BEGIN TRY EXEC dbo.CRM_Select_WorkGuide_Categories @Actor_ID=2;THROW 51299,'Owner read categories',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51200 THROW;END CATCH;
BEGIN TRY EXEC dbo.CRM_Save_WorkGuide_Category @Actor_ID=1,@Data=N'<row><Brand_ID>1</Brand_ID><Name_AR>ناقص</Name_AR><Sort_Order>0</Sort_Order></row>';THROW 51299,'Missing English category saved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
BEGIN TRY EXEC dbo.CRM_Save_WorkGuide_Category @Actor_ID=1,@Data=N'<row><Brand_ID>1</Brand_ID><Name_AR>ناقص</Name_AR><Name_EN>Missing order</Name_EN></row>';THROW 51299,'Missing category order saved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
SET @Data=CONVERT(xml,CONCAT(N'<row><Brand_ID>1</Brand_ID><Parent_ID>',@Child,N'</Parent_ID><Name_AR>دورة</Name_AR><Name_EN>Cycle</Name_EN><Sort_Order>0</Sort_Order></row>'));
BEGIN TRY EXEC dbo.CRM_Save_WorkGuide_Category @Actor_ID=1,@ID=@Root,@Data=@Data,@Version=@RootVersion;THROW 51299,'Category cycle accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
IF EXISTS(SELECT 1 FROM dbo.CRM_WorkGuide_Categories WHERE ID=@Root AND Parent_ID IS NOT NULL) THROW 51299,'Cycle rejection wrote data',1;
BEGIN TRY EXEC dbo.CRM_Delete_WorkGuide_Category @Actor_ID=1,@ID=@Root,@Version=@RootVersion;THROW 51299,'Parent category deleted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
INSERT @Results VALUES(N'Administrator-only reads/writes, bilingual category/order validation, tree cycle and linked-child deletion guards');
DECLARE @Categories xml=CONVERT(xml,CONCAT(N'<categories><id>',@Child,N'</id><id>',@Other,N'</id></categories>'));
SET @Data=N'<row><Brand_ID>1</Brand_ID><Name_AR>دليل SQL</Name_AR><Name_EN>SQL Guide</Name_EN><Summary_AR>ملخص عربي</Summary_AR><Summary_EN>English summary</Summary_EN><Sort_Order>5</Sort_Order><Is_Active>1</Is_Active><File_Url>/FileManager/CRMWorkGuide/11111111111111111111111111111111.pdf</File_Url><File_Name>test.pdf</File_Name><File_Extension>.pdf</File_Extension><File_Size>20</File_Size></row>';
INSERT @Saved EXEC dbo.CRM_Save_WorkGuide_Item @Actor_ID=1,@Data=@Data,@Categories=@Categories;
DECLARE @Guide int=(SELECT ID FROM @Saved),@Version binary(8)=(SELECT Row_Version FROM @Saved);DELETE @Saved;
IF (SELECT COUNT(*) FROM dbo.CRM_WorkGuide_ItemCategories WHERE Item_ID=@Guide)<>2 THROW 51299,'Multiple category links were lost',1;
IF NOT EXISTS(SELECT 1 FROM dbo.CRM_Activity_Logs WHERE Entity=N'WorkGuide_Items' AND Record_ID=@Guide AND After_Data.value('count(/row/Categories/category)','int')=2 AND After_Data.exist('/row/Summary_EN')=1) THROW 51299,'Guide audit snapshot incomplete',1;
DECLARE @ChildVersion binary(8)=(SELECT Row_Version FROM dbo.CRM_WorkGuide_Categories WHERE ID=@Child);
BEGIN TRY EXEC dbo.CRM_Delete_WorkGuide_Category @Actor_ID=1,@ID=@Child,@Version=@ChildVersion;THROW 51299,'Linked category deleted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
DECLARE @Invalid xml=N'<row><Brand_ID>1</Brand_ID><Name_AR>مرفوض</Name_AR><Name_EN>Denied Guide</Name_EN><Summary_AR>ملخص</Summary_AR><Summary_EN>Summary</Summary_EN><Sort_Order>0</Sort_Order><Is_Active>1</Is_Active></row>';
BEGIN TRY EXEC dbo.CRM_Save_WorkGuide_Item @Actor_ID=1,@Data=@Invalid,@Categories=@Categories;THROW 51299,'Guide created without file',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
BEGIN TRY EXEC dbo.CRM_Save_WorkGuide_Item @Actor_ID=1,@Data=@Data,@Categories=N'<categories><id>2147483647</id></categories>';THROW 51299,'Unknown category accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
DECLARE @Changed xml=CONVERT(xml,REPLACE(CONVERT(nvarchar(max),@Data),N'/FileManager/CRMWorkGuide/11111111111111111111111111111111.pdf',N'/FileManager/CRMWorkGuide/../../Web.config'));
BEGIN TRY EXEC dbo.CRM_Save_WorkGuide_Item @Actor_ID=1,@ID=@Guide,@Version=@Version,@Data=@Changed,@Categories=@Categories;THROW 51299,'Forged file path accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
SET @Changed=CONVERT(xml,REPLACE(CONVERT(nvarchar(max),@Data),N'<Summary_EN>English summary</Summary_EN>',N''));
BEGIN TRY EXEC dbo.CRM_Save_WorkGuide_Item @Actor_ID=1,@ID=@Guide,@Version=@Version,@Data=@Changed,@Categories=@Categories;THROW 51299,'Missing English summary saved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
SET @Changed=CONVERT(xml,REPLACE(CONVERT(nvarchar(max),@Data),N'<File_Size>20</File_Size>',N'<File_Size>10485761</File_Size>'));
BEGIN TRY EXEC dbo.CRM_Save_WorkGuide_Item @Actor_ID=1,@ID=@Guide,@Version=@Version,@Data=@Changed,@Categories=@Categories;THROW 51299,'Oversized file metadata accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
IF NOT EXISTS(SELECT 1 FROM dbo.CRM_WorkGuide_Items WHERE ID=@Guide AND Row_Version=@Version) THROW 51299,'Failed save modified guide/version',1;
INSERT @Results VALUES(N'Multiple category links, bilingual item/summary validation, required file, safe URL/size metadata and atomic failure');
DECLARE @OldUrl nvarchar(260)=(SELECT File_Url FROM dbo.CRM_WorkGuide_Items WHERE ID=@Guide);
SET @Changed=N'<row><Brand_ID>1</Brand_ID><Name_AR>دليل SQL معدل</Name_AR><Name_EN>Edited SQL Guide</Name_EN><Summary_AR>ملخص معدل</Summary_AR><Summary_EN>Edited summary</Summary_EN><Sort_Order>3</Sort_Order><Is_Active>1</Is_Active></row>';
INSERT @Saved EXEC dbo.CRM_Save_WorkGuide_Item @Actor_ID=1,@ID=@Guide,@Version=@Version,@Data=@Changed,@Categories=@Categories;DELETE @Saved;
IF NOT EXISTS(SELECT 1 FROM dbo.CRM_WorkGuide_Items WHERE ID=@Guide AND File_Url=@OldUrl AND Sort_Order=3) THROW 51299,'Edit without upload lost file',1;
BEGIN TRY EXEC dbo.CRM_Set_WorkGuide_Active @Actor_ID=1,@ID=@Guide,@Is_Active=0,@Version=@Version;THROW 51299,'Stale status changed',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
SELECT @Version=Row_Version FROM dbo.CRM_WorkGuide_Items WHERE ID=@Guide;
EXEC dbo.CRM_Set_WorkGuide_Active @Actor_ID=1,@ID=@Guide,@Is_Active=0,@Version=@Version;
BEGIN TRY EXEC dbo.CRM_Delete_WorkGuide_Item @Actor_ID=1,@ID=@Guide,@Version=@Version;THROW 51299,'Stale delete accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
SELECT @Version=Row_Version FROM dbo.CRM_WorkGuide_Items WHERE ID=@Guide;
BEGIN TRY EXEC dbo.CRM_Delete_WorkGuide_Item @Actor_ID=2,@ID=@Guide,@Version=@Version;THROW 51299,'Owner deleted guide',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51200 THROW;END CATCH;
BEGIN TRY EXEC dbo.CRM_WorkGuide_File @Actor_ID=2,@ID=@Guide;THROW 51299,'Owner downloaded guide',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51200 THROW;END CATCH;
EXEC dbo.CRM_Delete_WorkGuide_Item @Actor_ID=1,@ID=@Guide,@Version=@Version;
BEGIN TRY EXEC dbo.CRM_WorkGuide_File @Actor_ID=1,@ID=@Guide;THROW 51299,'Deleted guide file returned',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
IF NOT EXISTS(SELECT 1 FROM dbo.CRM_WorkGuide_Items WHERE ID=@Guide AND Is_Deleted=1 AND Is_Active=0 AND File_Url=@OldUrl) THROW 51299,'Soft delete metadata/file history lost',1;
IF (SELECT COUNT(*) FROM dbo.CRM_Activity_Logs WHERE Entity=N'WorkGuide_Items' AND Record_ID=@Guide AND After_Data IS NOT NULL)<>4 OR EXISTS(SELECT 1 FROM dbo.CRM_Activity_Logs WHERE Entity=N'WorkGuide_Items' AND Record_ID=@Guide AND Action<>N'إضافة' AND Before_Data IS NULL) THROW 51299,'Guide mutation audit incomplete',1;
EXEC dbo.CRM_Delete_WorkGuide_Category @Actor_ID=1,@ID=@Child,@Version=@ChildVersion;
EXEC dbo.CRM_Delete_WorkGuide_Category @Actor_ID=1,@ID=@Root,@Version=@RootVersion;
DECLARE @OtherVersion binary(8)=(SELECT Row_Version FROM dbo.CRM_WorkGuide_Categories WHERE ID=@Other);
EXEC dbo.CRM_Delete_WorkGuide_Category @Actor_ID=1,@ID=@Other,@Version=@OtherVersion;
INSERT @Results VALUES(N'File preservation, optimistic edit/status/delete versions, owner/download denial, soft-delete history and complete mutation audit');
SELECT * FROM @Results;
